<?php
namespace xdecaro\Component\Organizations\Administrator\Service;
defined('_JEXEC') or die;use Joomla\CMS\Factory;use Joomla\Database\DatabaseInterface;use RuntimeException;
final class DuplicateService{public function __construct(private DatabaseInterface $db){}public function find(int $limit=100):array{$u=Factory::getApplication()->getIdentity();if(!$u->authorise('core.manage','com_xdecaroorganizations')&&!$u->authorise('core.admin','com_xdecaroorganizations'))throw new RuntimeException('Not authorised.',403);$limit=max(1,min(500,$limit));$out=[];foreach(['code','email'] as $field){$q=$this->db->getQuery(true)->select(['LOWER(TRIM('.$this->db->quoteName($field).')) AS duplicate_key','COUNT(*) AS total'])->from($this->db->quoteName('#__xdecaroorganizations_organizations'))->where($this->db->quoteName('state').' >= 0')->where($this->db->quoteName($field).' IS NOT NULL')->where($this->db->quoteName($field)." <> ''")->group('LOWER(TRIM('.$this->db->quoteName($field).'))')->having('COUNT(*) > 1')->order('total DESC');foreach((array)$this->db->setQuery($q,0,$limit)->loadAssocList() as $r)$out[]=['type'=>$field,'key'=>$r['duplicate_key'],'count'=>(int)$r['total']];}if($u->authorise('organizations.view_sensitive','com_xdecaroorganizations')||$u->authorise('core.admin','com_xdecaroorganizations'))foreach(['vat_id','tax_identifier'] as $field){$q=$this->db->getQuery(true)->select(['UPPER(TRIM('.$this->db->quoteName($field).')) AS duplicate_key','COUNT(*) AS total'])->from($this->db->quoteName('#__xdecaroorganizations_organizations'))->where($this->db->quoteName('state').' >= 0')->where($this->db->quoteName($field).' IS NOT NULL')->where($this->db->quoteName($field)." <> ''")->group('UPPER(TRIM('.$this->db->quoteName($field).'))')->having('COUNT(*) > 1')->order('total DESC');foreach((array)$this->db->setQuery($q,0,$limit)->loadAssocList() as $r)$out[]=['type'=>$field,'key'=>$r['duplicate_key'],'count'=>(int)$r['total']];}return $out;}}
